{
  "scenes": [
    {
      "scene": 1,
      "name": "杂乱桌面",
      "purpose": "建立共鸣，呈现问题状态"
    },
    {
      "scene": 2,
      "name": "三步整理",
      "purpose": "展示清晰可执行的动作"
    },
    {
      "scene": 3,
      "name": "干净桌面与开工",
      "purpose": "给出结果与行动号召"
    }
  ],
  "shots": [
    {
      "shot_id": "S1-01",
      "scene": 1,
      "description": "俯拍堆满咖啡杯、纸张和线材的桌面，画面轻微手持晃动，突出拥挤感。"
    },
    {
      "shot_id": "S1-02",
      "scene": 1,
      "description": "中景稍低角度拍主角看着桌面叹气，手指轻敲桌面，字幕打出'桌面越乱，脑子越吵'。"
    },
    {
      "shot_id": "S2-01",
      "scene": 2,
      "description": "正俯拍手部动作：把视线正前方区域只留电脑、水杯、笔，其余推到画面一侧。"
    },
    {
      "shot_id": "S2-02",
      "scene": 2,
      "description": "特写插入镜头：文具放进笔筒、线材收进抽屉、纸张叠齐放入文件架，三个动作快切。"
    },
    {
      "shot_id": "S2-03",
      "scene": 2,
      "description": "近景拍手把散落物品放进一个带盖的收纳盒，然后盖上盖子，动作干净利落。"
    },
    {
      "shot_id": "S3-01",
      "scene": 3,
      "description": "俯拍整理后的桌面全景，干净留白，光线明亮，主角深呼吸一次入画。"
    },
    {
      "shot_id": "S3-02",
      "scene": 3,
      "description": "中景主角坐下，打开笔记本开始工作，镜头缓缓后退收尾，画面上方叠加标题字卡。"
    }
  ]
}
